import{_ as c,r as t,o as l,c as i,e as p,a as n,d as a,s as u}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Поведения - October CMS - 3.x","titleTemplate":false,"description":"Объединяйте классы с общей функциональностью.","frontmatter":{"subtitle":"Объединяйте классы с общей функциональностью."},"headers":[{"level":2,"title":"Сравнение с трейтами","slug":"сравнение-с-треитами","link":"#сравнение-с-треитами","children":[]},{"level":2,"title":"Расширение конструкторов","slug":"расширение-конструкторов","link":"#расширение-конструкторов","children":[{"level":3,"title":"Мягкое определение","slug":"мягкое-определение","link":"#мягкое-определение","children":[]}]},{"level":2,"title":"Динамическая реализация поведения","slug":"динамическая-реализация-поведения","link":"#динамическая-реализация-поведения","children":[]},{"level":2,"title":"Динамическое создание методов","slug":"динамическое-создание-методов","link":"#динамическое-создание-методов","children":[{"level":3,"title":"Проверка существования метода","slug":"проверка-существования-метода","link":"#проверка-существования-метода","children":[]},{"level":3,"title":"Список всех доступных методов","slug":"список-всех-доступных-методов","link":"#список-всех-доступных-методов","children":[]}]},{"level":2,"title":"Пример использования","slug":"пример-использования","link":"#пример-использования","children":[{"level":3,"title":"Класс поведения / расширения","slug":"класс-поведения-расширения","link":"#класс-поведения-расширения","children":[]},{"level":3,"title":"Расширение класса","slug":"расширение-класса","link":"#расширение-класса","children":[]},{"level":3,"title":"Использование расширения","slug":"использование-расширения","link":"#использование-расширения","children":[]}]}],"relativePath":"3.x/ru/extend/system/behaviors.md","filePath":"3.x/ru/extend/system/behaviors.md"}'),r={name:"3.x/ru/extend/system/behaviors.md"};function k(d,s,h,g,m,f){const e=t("pre-heading"),o=t("post-heading");return l(),i("div",null,[p(e),s[0]||(s[0]=n("h1",null,"Поведения",-1)),p(o),s[1]||(s[1]=n("p",null,[a("Поведения добавляют возможность классам иметь приватные трейты, аналогичные "),n("a",{href:"http://php.net/manual/en/language.oop5.traits.php",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("нативным PHP-трейтам"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),n("span",{class:"sr-only"},"(opens new window)")])]),a(", но с некоторыми отличительными преимуществами.")],-1)),s[2]||(s[2]=u(`<ol><li>Поведения используют собственный конструктор.</li><li>Поведения могут иметь приватные или защищённые методы.</li><li>Конфликты имён методов и свойств разрешаются безопасно.</li><li>Классы могут быть расширены поведениями динамически.</li></ol><h2 id="сравнение-с-треитами"><a href="#сравнение-с-треитами" class="header-anchor">#</a> Сравнение с трейтами</h2><p>Где вы можете использовать PHP-трейт вот так.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">MyClass</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>UtilityFunctions</span><span class="token punctuation">;</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>DeferredBinding</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Поведение используется аналогичным образом.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">MyClass</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Extension<span class="token punctuation">\\</span>Extendable</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>UtilityFunctions</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>DeferredBinding</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Где вы можете определить трейт вот так.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">trait</span> <span class="token class-name-definition class-name">UtilityFunctions</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">sayHello</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">echo</span> <span class="token string double-quoted-string">&quot;Hello from &quot;</span> <span class="token operator">.</span> <span class="token function">get_class</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Поведение определяется вот так.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">UtilityFunctions</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Extension<span class="token punctuation">\\</span>ExtensionBase</span>
<span class="token punctuation">{</span>
    <span class="token keyword">protected</span> <span class="token variable">$parent</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__construct</span><span class="token punctuation">(</span><span class="token variable">$parent</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">parent</span> <span class="token operator">=</span> <span class="token variable">$parent</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">sayHello</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">echo</span> <span class="token string double-quoted-string">&quot;Hello from &quot;</span> <span class="token operator">.</span> <span class="token function">get_class</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">parent</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Расширяемый объект всегда передаётся как первый аргумент конструктора. В итоге, при использовании поведений наследуйте следующие классы.</p><ul><li>Наследуйте <code>October\\Rain\\Extension\\ExtensionBase</code> для объявления класса как поведения.</li><li>Наследуйте <code>October\\Rain\\Extension\\Extendable</code> для класса, реализующего поведение.</li></ul><h2 id="расширение-конструкторов"><a href="#расширение-конструкторов" class="header-anchor">#</a> Расширение конструкторов</h2><p>Любой класс, наследующий <code>Extendable</code>, может расширить свой конструктор статическим методом <code>extend</code>. Аргумент должен быть замыканием, которое будет вызвано как часть конструктора класса.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">MyClass</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="мягкое-определение"><a href="#мягкое-определение" class="header-anchor">#</a> Мягкое определение</h3><p>Если класс поведения не существует, как в случае с трейтом, будет выброшена ошибка <strong>class not found</strong>. В некоторых случаях вы можете захотеть подавить эту ошибку для условной реализации, если поведение присутствует в системе. Это можно сделать, поставив символ <code>@</code> в начало имени класса. В следующем примере, если класс <code>RainLab\\Translate\\Behaviors\\TranslatableModel</code> не существует, ошибка не будет выброшена.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Extension<span class="token punctuation">\\</span>Extendable</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;@&#39;</span><span class="token operator">.</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>RainLab<span class="token punctuation">\\</span>Translate<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>TranslatableModel</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="динамическая-реализация-поведения"><a href="#динамическая-реализация-поведения" class="header-anchor">#</a> Динамическая реализация поведения</h2><p>Эта уникальная возможность расширения конструкторов позволяет реализовывать поведения динамически. Например, используйте метод <code>implementClassWith</code> для реализации класса <code>RelationController</code> в классе <code>UsersController</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">UsersController</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">implementClassWith</span><span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>RelationController</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>Метод <code>implementClassWith</code> можно безопасно вызывать несколько раз — он проверит, реализует ли класс уже данное поведение, и реализует его.</p></div><p>Используйте метод <code>extendClassWith</code> для расширения объекта после его создания. Следующий пример динамически расширяет класс Model, используя имя класса, хранящееся в базе данных.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">afterFetch</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">extendClassWith</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">class_type</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Чтобы проверить, был ли объект расширен поведением, используйте метод <code>isClassExtendedWith</code> на объекте.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">isClassExtendedWith</span><span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>RelationController</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Для явного вызова метода из поведения используйте метод <code>asExtension</code>, который принимает базовое имя класса или полное имя класса как аргумент.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">echo</span> <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">asExtension</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;RelationController&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">otherMethod</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="динамическое-создание-методов"><a href="#динамическое-создание-методов" class="header-anchor">#</a> Динамическое создание методов</h2><p>Методы могут быть созданы для расширяемого объекта вызовом <code>addDynamicMethod</code> с передачей имени метода и вызываемого объекта, например <code>Closure</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">MyModel</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">addDynamicMethod</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;getTagsAttribute&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;...&#39;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="проверка-существования-метода"><a href="#проверка-существования-метода" class="header-anchor">#</a> Проверка существования метода</h3><p>Для проверки существования метода в классе <code>Extendable</code> вызовите метод <code>methodExists</code> — аналогично PHP-функции <code>method_exists()</code>. Это обнаружит как стандартные методы, методы в поведениях, так и динамические методы, добавленные через вызов <code>addDynamicMethod</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Post</span><span class="token punctuation">;</span>
<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">methodExists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;getTagsAttribute&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// true</span>
<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">methodExists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;missingMethod&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// false</span>
</code></pre></div><h3 id="список-всех-доступных-методов"><a href="#список-всех-доступных-методов" class="header-anchor">#</a> Список всех доступных методов</h3><p>Для получения списка всех доступных методов в классе <code>Extendable</code> используйте метод <code>getClassMethods</code>. Этот метод работает аналогично PHP-функции <code>get_class_methods()</code> в том, что возвращает массив доступных методов в классе, но дополнительно перечисляет методы, предоставленные расширением или добавленные через вызов <code>addDynamicMethod</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Post</span><span class="token punctuation">;</span>
<span class="token variable">$methods</span> <span class="token operator">=</span> <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">getClassMethods</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">/**
 * $methods = [
 *   0 =&gt; &#39;__construct&#39;,
 *   1 =&gt; &#39;extend&#39;,
 *   2 =&gt; &#39;getTagsAttribute&#39;,
 *   ...
 * ];
 */</span>
</code></pre></div><h2 id="пример-использования"><a href="#пример-использования" class="header-anchor">#</a> Пример использования</h2><h3 id="класс-поведения-расширения"><a href="#класс-поведения-расширения" class="header-anchor">#</a> Класс поведения / расширения</h3><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">MyNamespace<span class="token punctuation">\\</span>Behaviors</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">FormController</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Extension<span class="token punctuation">\\</span>ExtensionBase</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * @var Controller controller is a reference to the extended object.
     */</span>
    <span class="token keyword">protected</span> <span class="token variable">$controller</span><span class="token punctuation">;</span>

    <span class="token comment">/**
     * __construct
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__construct</span><span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">controller</span> <span class="token operator">=</span> <span class="token variable">$controller</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">someMethod</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token string double-quoted-string">&quot;I come from the FormController Behavior!&quot;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">otherMethod</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token string double-quoted-string">&quot;You might not see me...&quot;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="расширение-класса"><a href="#расширение-класса" class="header-anchor">#</a> Расширение класса</h3><p>Этот класс <code>Controller</code> реализует поведение <code>FormController</code>, и затем методы станут доступны (подмешаны) в класс. Мы переопределим метод <code>otherMethod</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">namespace</span> <span class="token package">MyNamespace</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Controller</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Extension<span class="token punctuation">\\</span>Extendable</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * implement the FormController behavior
     */</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>MyNamespace<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>FormController</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">otherMethod</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token string double-quoted-string">&quot;I come from the main Controller!&quot;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</span></code></pre></div><h3 id="использование-расширения"><a href="#использование-расширения" class="header-anchor">#</a> Использование расширения</h3><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$controller</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name class-name-fully-qualified">MyNamespace<span class="token punctuation">\\</span>Controller</span><span class="token punctuation">;</span>

<span class="token comment">// Prints: I come from the FormController Behavior!</span>
<span class="token keyword">echo</span> <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">someMethod</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Prints: I come from the main Controller!</span>
<span class="token keyword">echo</span> <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">otherMethod</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Prints: You might not see me...</span>
<span class="token keyword">echo</span> <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">asExtension</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;FormController&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">otherMethod</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,45))])}const b=c(r,[["render",k]]);export{y as __pageData,b as default};
